// One message for the whole agency, not one per clinic. A channel that
// fires six times every morning gets muted within a fortnight.
//
// Severity is by SHARE, not by amount and not by age alone. Every front desk
// leaves a few stragglers, so a raw count ranks clinics by size and an average
// age finds whoever has the oldest single straggler -- neither is the signal.
// A desk that has stopped recording leaves a hole, and a hole is a percentage.
// The dashboard flags on the same two numbers, so the alert and the dashboard
// never disagree about who has stopped.

const STOPPED_PCT  = 8;
const STOPPED_DAYS = 7;

const rows = $input.all().map(i => i.json);

const money = n => '$' + Number(n || 0).toFixed(2);
const totalRisk  = rows.reduce((s, r) => s + Number(r.revenue_at_risk_usd || 0), 0);
const totalCount = rows.reduce((s, r) => s + Number(r.unmarked || 0), 0);

const hasStopped = r =>
  Number(r.unmarked_pct) >= STOPPED_PCT && Number(r.avg_days_stale) >= STOPPED_DAYS;

const stopped = rows.filter(hasStopped);

const lines = rows.map(r => {
  const days = Number(r.avg_days_stale).toFixed(0);
  const pct  = Number(r.unmarked_pct).toFixed(1);
  const flag = hasStopped(r) ? ' :warning:' : '';
  return '• *' + r.business_name + '* — ' + r.unmarked + ' unmarked (' + pct + '%), '
       + money(r.revenue_at_risk_usd) + ' not invoiced, avg ' + days + 'd old' + flag;
});

const header = '*' + totalCount + ' appointments never marked* — '
             + money(totalRisk) + ' not invoiced';

let footer = '_Nothing is auto-marked. Guessing an outcome to clear an alert is how a billing system starts inventing revenue._';

if (stopped.length) {
  const names = stopped.map(r => r.business_name).join(', ');
  footer = ':rotating_light: *' + names + '* — ' + STOPPED_PCT
         + '%+ of appointments unmarked and averaging over a week. That is a front desk '
         + 'that has stopped recording attendance, not a backlog. Every other number for '
         + 'them is degrading with it.\n\n' + footer;
}

return [{
  json: {
    clinics: rows.length,
    total_unmarked: totalCount,
    total_at_risk_usd: Number(totalRisk.toFixed(2)),
    stopped_clinics: stopped.length,
    text: [header, '', ...lines, '', footer].join('\n')
  }
}];
